#include <stdio.h>
#include <queue>
#include <ctype.h>
#include <vector>
#include <string.h>
using namespace std;

#define INF 12345678

struct Point {
    int x, y, id;
};

struct Bucket {
    int vals[1000];
    int cnt;
    int active;
};

Bucket buckets[100][100];
vector<int> adjList[1000];
int size, limit;
int leftSide[1000], rightSide[1000], color[1000];
char gridSrc[1000][1000], gridDst[1000][1000];
int distSrc[1000][1000], distDst[1000][1000];
queue<Point> qq;

void bfsSource(Point s);
void bfsDest(Point s);
int maxMatch(int nodes);
bool tryAugment(int u);

int main() {
    int i, j, k, l;
    Point p, q;

    scanf("%d %d", &size, &limit);

    for (i = 0; i <= size; i++)
        for (j = 0; j <= size; j++)
            distSrc[i][j] = INF;

    for (i = 0; i < size; i++) scanf("%s", gridSrc[i]);
    for (i = 0; i < size; i++) scanf("%s", gridDst[i]);

    for (i = 0; i < size; i++)
        for (j = 0; j < size; j++)
            if (gridSrc[i][j] == 'Z') {
                p.x = i; p.y = j;
                bfsSource(p);
            }

    int idx = 1;
    for (i = 0; i < size; i++)
        for (j = 0; j < size; j++)
            if (isdigit(gridDst[i][j])) {
                k = gridDst[i][j] - '0';
                if (k > 0) buckets[i][j].active = 1;
                buckets[i][j].cnt = k;
                for (l = 1; l <= k; l++)
                    buckets[i][j].vals[l] = idx++;
            }

    idx = 1;
    for (i = 0; i < size; i++)
        for (j = 0; j < size; j++)
            if (isdigit(gridSrc[i][j])) {
                k = gridSrc[i][j] - '0';
                for (l = 1; l <= k; l++) {
                    p.x = i; p.y = j; p.id = idx++;
                    bfsDest(p);
                }
            }

    printf("%d\n", maxMatch(idx - 1));
    return 0;
}

bool tryAugment(int u) {
    if (color[u]) return false;
    color[u] = 1;
    for (int i = 0; i < (int)adjList[u].size(); i++) {
        int v = adjList[u][i];
        if (leftSide[v] == -1) {
            leftSide[v] = u;
            rightSide[u] = i;
            return true;
        } else if (tryAugment(leftSide[v])) {
            leftSide[v] = u;
            rightSide[u] = i;
            return true;
        }
    }
    return false;
}

int maxMatch(int nodes) {
    memset(leftSide, -1, sizeof(leftSide));
    memset(rightSide, -1, sizeof(rightSide));
    bool changed;
    do {
        changed = false;
        memset(color, 0, sizeof(color));
        for (int i = 1; i <= nodes; i++)
            if (rightSide[i] == -1 && tryAugment(i))
                changed = true;
    } while (changed);
    int res = 0;
    for (int i = 1; i <= nodes; i++)
        if (rightSide[i] != -1) res++;
    return res;
}

void bfsDest(Point s) {
    int i, j, k, l;
    Point p, q;
    for (i = 0; i <= size; i++)
        for (j = 0; j <= size; j++)
            distDst[i][j] = INF;
    i = s.x; j = s.y;
    distDst[i][j] = 0;
    qq.push(s);
    while (!qq.empty()) {
        p = qq.front(); qq.pop();
        i = p.x; j = p.y;
        if (distDst[i][j] > limit) continue;
        if (gridSrc[i][j] == 'Y') continue;
        if (buckets[i][j].active) {
            if (distDst[i][j] <= limit && distDst[i][j] <= distSrc[i][j]) {
                for (k = 1; k <= buckets[i][j].cnt; k++)
                    adjList[s.id].push_back(buckets[i][j].vals[k]);
            }
        }
        if (distDst[i][j] >= distSrc[i][j]) continue;
        // up
        if (i - 1 >= 0 && distDst[i - 1][j] > distDst[i][j] + 1) {
            distDst[i - 1][j] = distDst[i][j] + 1;
            q.x = i - 1; q.y = j;
            qq.push(q);
        }
        // down
        if (i + 1 < size && distDst[i + 1][j] > distDst[i][j] + 1) {
            distDst[i + 1][j] = distDst[i][j] + 1;
            q.x = i + 1; q.y = j;
            qq.push(q);
        }
        // left
        if (j - 1 >= 0 && distDst[i][j - 1] > distDst[i][j] + 1) {
            distDst[i][j - 1] = distDst[i][j] + 1;
            q.x = i; q.y = j - 1;
            qq.push(q);
        }
        // right
        if (j + 1 < size && distDst[i][j + 1] > distDst[i][j] + 1) {
            distDst[i][j + 1] = distDst[i][j] + 1;
            q.x = i; q.y = j + 1;
            qq.push(q);
        }
    }
}

void bfsSource(Point s) {
    int i, j;
    Point p, q;
    i = s.x; j = s.y;
    distSrc[i][j] = 0;
    qq.push(s);
    while (!qq.empty()) {
        p = qq.front(); qq.pop();
        i = p.x; j = p.y;
        if (gridSrc[i][j] == 'Y') continue;
        // up
        if (i - 1 >= 0 && distSrc[i - 1][j] > distSrc[i][j] + 1) {
            distSrc[i - 1][j] = distSrc[i][j] + 1;
            q.x = i - 1; q.y = j;
            qq.push(q);
        }
        // down
        if (i + 1 < size && distSrc[i + 1][j] > distSrc[i][j] + 1) {
            distSrc[i + 1][j] = distSrc[i][j] + 1;
            q.x = i + 1; q.y = j;
            qq.push(q);
        }
        // left
        if (j - 1 >= 0 && distSrc[i][j - 1] > distSrc[i][j] + 1) {
            distSrc[i][j - 1] = distSrc[i][j] + 1;
            q.x = i; q.y = j - 1;
            qq.push(q);
        }
        // right
        if (j + 1 < size && distSrc[i][j + 1] > distSrc[i][j] + 1) {
            distSrc[i][j + 1] = distSrc[i][j] + 1;
            q.x = i; q.y = j + 1;
            qq.push(q);
        }
    }
}
